"""The Daily Fantasizer: phone layout (ported 2026-10-19 from the phone version of the week 5 page,
which was hand-tuned in the Claude copy). Tables become stacked cards on phones; the cards need every
<td> tagged with its role and column label, which tag() does from the column headers, so render.py
and players.py --patch can rebuild it every week. PHONE_CSS / JUMP_NAV / PHONE_JS live in template.html."""
import html as _html, re

ROLE = {"#": "c-rk", "Team": "c-name", "Player": "c-name", "Owner": "c-own"}
WIDE = {"Notes", "Games that flip"}
KEYS = ["Proj", "Pts vs proj", "Pos rank", "PPR/g"]  # the stat each Player Stats card leads with


def _text(h):
    return _html.unescape(re.sub(r"<[^>]+>", "", h)).strip()


def _tag_table(m):
    attrs, body = m.group(1), m.group(2)
    cls = (re.search(r'class="([^"]*)"', attrs) or [None, ""])[1].split()
    if "mcards" in cls:
        return m.group(0)
    ths = [_text(x) for x in re.findall(r"<th[^>]*>(.*?)</th>", body, re.S)]
    if not ths:
        return m.group(0)
    pst = "pst" in cls
    role = [ROLE.get(h, "") for h in ths]
    wide = [h in WIDE or ("gr-all" in cls and h.startswith("Week ")) for h in ths]
    key = next((h for h in KEYS if h in ths), None) if pst else None
    if pst and "Target share" in ths:
        tail = {"Touches/g", "Air-yd share", "Last 3"}
    elif pst and "Pass att/g" in ths:
        tail = {"Snap %", "Last 3"}
    elif "gr-all" in cls:
        tail = {"Spots vs rank"} | {h for h in ths if h.startswith("Week ")}
    else:
        tail = set()
    new = ["mcards"] + (["has-own"] if "Owner" in ths else [])
    if pst:
        new.append(f"s{len(ths) - sum(1 for r in role if r) - 1}")
    new_cls = " ".join(new + cls)
    attrs = re.sub(r'\s*class="[^"]*"', "", attrs)
    head = f'<table class="{new_cls}"{attrs}>'

    def td_row(tr):
        cells = iter(range(len(ths)))

        def td(c):
            i = next(cells, None)
            if i is None:
                return c.group(0)
            a = c.group(1)
            old = (re.search(r'class="([^"]*)"', a) or [None, ""])[1].split()
            rest = re.sub(r'\s*class="[^"]*"', "", a)
            pre = [role[i]] if role[i] else []
            if wide[i]:
                pre.append("c-wide")
            if key and ths[i] == key:
                pre.append("c-key")
            k = " ".join(pre + old)
            return ('<td' + (' data-tail="1"' if ths[i] in tail else '') + (f' class="{k}"' if k else '') + rest
                    + f' data-label="{_html.escape(ths[i], quote=True)}">')
        return re.sub(r"<td([^>]*)>", td, tr.group(0))
    body = re.sub(r"<tbody>.*?</tbody>", lambda b: re.sub(r"<tr[^>]*>.*?</tr>", td_row, b.group(0), flags=re.S), body, flags=re.S)
    return head + body + "</table>"


def tag(page):
    return re.sub(r"<table([^>]*)>(.*?)</table>", _tag_table, page, flags=re.S)


