PHONE_JS = '<script>\n(function(){\n  if(!window.matchMedia||!matchMedia(\'(max-width:760px), (pointer:coarse) and (max-width:1100px)\').matches)return;\n  document.querySelectorAll(\'#player-stats table.mcards.pst\').forEach(function(t){\n    if(t.closest(\'.gr-every\'))return;\n    var n=t.tBodies[0]?t.tBodies[0].rows.length:0; if(n<=12)return;\n    t.classList.add(\'clip\');\n    var b=document.createElement(\'button\'); b.type=\'button\'; b.className=\'ps-more on\';\n    b.textContent=\'Show all \'+n; b.setAttribute(\'aria-expanded\',\'false\');\n    b.addEventListener(\'click\',function(){var open=t.classList.toggle(\'clip\');\n      b.textContent=open?\'Show all \'+n:\'Show top 10\'; b.setAttribute(\'aria-expanded\',String(!open));\n      if(open)t.scrollIntoView({block:\'start\'});});\n    (t.closest(\'.tbl-wrap\')||t).after(b);\n  });\n})();\n</script>\n<button type="button" class="m-top" aria-label="Back to top" style="display:none">TOP</button>\n<script>\n(function(){\n  var mq=window.matchMedia&&matchMedia(\'(max-width:760px), (pointer:coarse) and (max-width:1100px)\'); if(!mq||!mq.matches)return;\n  var top=document.querySelector(\'.m-top\'); top.style.display=\'\';\n  addEventListener(\'scroll\',function(){top.classList.toggle(\'show\',scrollY>innerHeight*1.5)},{passive:true});\n  top.addEventListener(\'click\',function(){scrollTo({top:0,behavior:\'smooth\'})});\n  var st=document.getElementById(\'tab-stats\');\n  if(st)st.addEventListener(\'click\',function(){scrollTo({top:0})});\n  document.querySelectorAll(\'#player-stats .pj\').forEach(function(l){\n    var rows=l.querySelectorAll(\'.pj-row\'),n=rows.length; if(n<=12)return;\n    function set(open){for(var i=10;i<n;i++)rows[i].style.display=open?\'\':\'none\';}\n    set(false);\n    var b=document.createElement(\'button\'); b.type=\'button\'; b.className=\'ps-more on\'; b.textContent=\'Show all \'+n;\n    var open=false; b.addEventListener(\'click\',function(){open=!open;set(open);b.textContent=open?\'Show top 10\':\'Show all \'+n; if(!open)l.scrollIntoView({block:\'start\'});});\n    l.after(b);\n  });\n})();\n</script>\n'
